package com.truckload.controller.featuretests;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import com.truckload.controller.*;
public class V4Instrumentation extends Instrumentation {
 MainActivity a;Telemetry m;Object v4;List<String> results=new ArrayList<>();
 Object field(Object obj,String name)throws Exception{Field f=obj.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(obj);}
 void set(Object obj,String name,Object value)throws Exception{Field f=obj.getClass().getDeclaredField(name);f.setAccessible(true);f.set(obj,value);}
 Object call(Object obj,String name,Class<?>[] types,Object...values)throws Exception{Method method=obj.getClass().getDeclaredMethod(name,types);method.setAccessible(true);return method.invoke(obj,values);}
 void update()throws Exception{call(a,"update",new Class<?>[]{});}
 TextView find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView result=find(((ViewGroup)v).getChildAt(i),text);if(result!=null)return result;}return null;}
 void check(boolean ok,String text){if(!ok)throw new AssertionError(text);results.add("PASS: "+text);}
 void ui(Work work){runOnMainSync(()->{try{work.run();}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();}
 interface Work{void run()throws Exception;}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 void shot(String file)throws Exception{Thread.sleep(400);try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),file))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
 @Override public void onStart(){Bundle report=new Bundle();try{
 a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));m=(Telemetry)field(a,"model");v4=field(a,"improvements");
 ui(()->{((Handler)field(a,"handler")).removeCallbacksAndMessages(null);call(a,"showTab",new Class<?>[]{int.class},0);check(!((Button)field(v4,"work")).isEnabled(),"quick work lights disabled without controller-confirmed state");call(a,"colorDialog",new Class<?>[]{int.class},0);});
 // Discover the palette dialog through its accessible window rather than production test hooks.
 Thread.sleep(600);shot("v4-palette-debug.png");android.view.accessibility.AccessibilityNodeInfo palette=getUiAutomation().getRootInActiveWindow();check(palette!=null&&!palette.findAccessibilityNodeInfosByText("Custom hexadecimal").isEmpty(),"native palette dialog opens with custom hex entry");shot("v4-palette.png");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);Thread.sleep(300);
 ui(()->{set(a,"connected",true);m.apply("CAPS|2|DRIVING,BENCH,MAP");((FeaturePanels)field(a,"features")).showBench();update();List<?> zones=(List<?>)field(v4,"zones"),colors=(List<?>)field(v4,"testColors");check(!((Button)zones.get(1)).isEnabled()&&!((Button)colors.get(1)).isEnabled(),"firmware 0.6.1 cannot enable unsupported zone or color commands");m.bench=true;update();check(!((Button)zones.get(1)).isEnabled(),"old firmware keeps individual zones disabled even in bench");m.apply("CAPS|3|DRIVING,BENCH,MAP,BENCH_ZONES,BENCH_COLOR,ADC_RAW,FW_INFO");m.apply("FW_INFO|0.6.2|board|43|44");update();check(((Button)zones.get(1)).isEnabled()&&((Button)colors.get(1)).isEnabled(),"advertised companion capabilities enable actual zone and color tests");m.bench=false;update();check(!((Button)zones.get(1)).isEnabled(),"zone controls require explicit bench start");set(a,"connected",false);((AlertDialog)field(field(a,"features"),"benchDialog")).dismiss();});
 ui(()->{set(a,"connected",true);m.profile="EMULATOR FIXTURE";m.points=1;m.sensor="READY";m.psi=20;call(v4,"showCalibration",new Class<?>[]{});update();check(!((Button)field(v4,"wizardCapture")).isEnabled(),"calibration rejects stale sensor and pressure data");call(v4,"record",new Class<?>[]{String.class,String.class},"SENSOR","SENSOR|ON|READY|0.8|1.1|1000");call(v4,"record",new Class<?>[]{String.class,String.class},"T","T|20|-1|-1|20000|EMULATOR FIXTURE");call(v4,"record",new Class<?>[]{String.class,String.class},"BENCH_STATE","BENCH_STATE|0|LOAD|50|25|0|BOTH|MODE");update();check(((Button)field(v4,"wizardCapture")).isEnabled(),"fresh real ready sensor enables guided capture");m.bench=true;update();check(!((Button)field(v4,"wizardCapture")).isEnabled(),"guided calibration rejects bench simulation");m.bench=false;((AlertDialog)field(v4,"wizard")).dismiss();m.lightMode="WORK";call(v4,"record",new Class<?>[]{String.class,String.class},"LIGHT_STATE","LIGHT_STATE|WORK|BAR|140|255");update();check(((Button)field(v4,"work")).getText().toString().contains("ON"),"quick work control reflects confirmed controller state");set(v4,"pendingWork","LOAD");set(v4,"workSent",SystemClock.elapsedRealtime());update();check(!((Button)field(v4,"work")).isEnabled(),"unconfirmed work-light action cannot be toggled repeatedly");call(v4,"manual",new Class<?>[]{});check((Boolean)field(v4,"manualStop"),"manual disconnect suppresses automatic reconnect");set(a,"connected",false);set(v4,"pendingWork",null);update();});shot("v4-overview.png");
 try(FileWriter out=new FileWriter(new File(a.getExternalFilesDir(null),"v4-ui-tests.txt"))){for(String line:results)out.write(line+"\n");}report.putString("stream",String.join("\n",results));finish(Activity.RESULT_OK,report);
 }catch(Throwable e){report.putString("stream",e.toString());finish(Activity.RESULT_CANCELED,report);}}
}

